#!/usr/bin/env node
/**
 * Compiles source files into dist/ bundles for the npm package.
 *
 * Outputs:
 *   dist/setup-bundle.md      — all setup skill content inlined; agent reads this to run setup
 *   dist/workflow-bundle.md   — full .workflow/ tree in FILE markers; agent expands this post-setup
 *
 * Also populates:
 *   assets/adapters/          — rendered adapter shims (copied from adapters/ source)
 *   validators/               — validator scripts needed during setup (copied from .workflow/validators/)
 */

import { readFileSync, writeFileSync, mkdirSync, readdirSync, statSync, copyFileSync, existsSync } from 'node:fs';
import { join, dirname, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(dirname(fileURLToPath(import.meta.url)));

function read(rel) {
  return readFileSync(join(root, rel), 'utf8');
}

function write(rel, content) {
  const full = join(root, rel);
  mkdirSync(dirname(full), { recursive: true });
  writeFileSync(full, content, 'utf8');
  console.log(`wrote   ${rel}`);
}

function copyFile(src, dest) {
  const destFull = join(root, dest);
  mkdirSync(dirname(destFull), { recursive: true });
  copyFileSync(join(root, src), destFull);
  console.log(`copied  ${dest}`);
}

function walkFiles(dir, base = dir) {
  const results = [];
  for (const name of readdirSync(join(root, dir)).sort()) {
    const rel = join(dir, name);
    const stat = statSync(join(root, rel));
    if (stat.isDirectory()) {
      results.push(...walkFiles(rel, base));
    } else {
      results.push(rel.replaceAll('\\', '/'));
    }
  }
  return results;
}

// ─── setup-bundle.md ───────────────────────────────────────────────────────

const setupSections = [
  '<!-- compiled from setup/ sources — agent reads this to run the setup skill -->',
  '<!-- do not edit this file directly; edit setup/SKILL.md and setup/references/ then re-run build-bundle.mjs -->',
  '',
  read('setup/SKILL.md').trim(),
];

const refDir = join(root, 'setup/references');
const refFiles = readdirSync(refDir).filter(f => f.endsWith('.md')).sort();
for (const name of refFiles) {
  const content = readFileSync(join(refDir, name), 'utf8').trim();
  setupSections.push('', '---', '', content);
}

write('dist/setup-bundle.md', setupSections.join('\n') + '\n');

// ─── workflow-bundle.md ────────────────────────────────────────────────────

const WORKFLOW_EXCLUDES = new Set([
  '.workflow/config',
  '.workflow/artifacts',
  '.workflow/learnings/sessions',
]);

function isExcluded(rel) {
  return [...WORKFLOW_EXCLUDES].some(ex => rel === ex || rel.startsWith(ex + '/'));
}

const workflowFiles = walkFiles('.workflow').filter(rel => !isExcluded(rel) && !rel.endsWith('.gitkeep'));

const bundleLines = [
  '<!-- compiled from .workflow/ sources — agent expands FILE blocks into consumer repo as workflow/ -->',
  '<!-- do not edit this file directly; edit source files under .workflow/ then re-run build-bundle.mjs -->',
  '',
];

for (const rel of workflowFiles) {
  const content = read(rel);
  bundleLines.push(`<!-- FILE: ${rel.replace(/^\.workflow\//, 'workflow/')} -->`);
  bundleLines.push(content.trimEnd());
  bundleLines.push(`<!-- END FILE -->`);
  bundleLines.push('');
}

write('dist/workflow-bundle.md', bundleLines.join('\n') + '\n');

// ─── assets/adapters/ ─────────────────────────────────────────────────────

for (const rel of walkFiles('adapters')) {
  const dest = join('assets', rel);
  copyFile(rel, dest);
}

// ─── validators/ (setup-time copies) ──────────────────────────────────────

const setupValidators = ['lib.mjs', 'check-config.mjs', 'check-setup-complete.mjs'];
for (const name of setupValidators) {
  copyFile(`.workflow/validators/${name}`, `validators/${name}`);
}

console.log('\nbuild-bundle: ok');
